import {t,label,ui,markup,setText} from './language.mjs';
import {AccountStore,api} from './accounts.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function setupAccounts(onChange){
 const view=document.createElement('section');view.id='auth-view';view.hidden=true;
 view.innerHTML=ui`<header class="wrap site-header"><a class="brand" href="#home"><img src="assets/icon.svg" width="42" height="42" alt=""><span>E-Nay<small>CARE, CLOSER TO HOME</small></span></a><a class="text-link" href="#home">Back to home ↗</a></header><main id="auth-main" class="auth-layout wrap" tabindex="-1"><div class="auth-story"><p class="eyebrow">KASAMA MO SA PAG-AALAGA.</p><h1><span lang="fil">Tuloy po.</span><br><em>Your care starts here.</em></h1><p>Mothers and guardians can see care records shared by their health worker. Barangay health workers manage clinical records and vaccine stock in a separate staff workspace.</p><img src="assets/philippines-mother-child-small.webp" width="600" height="540" alt="A mother carrying her child at a viewpoint in Cagayan Valley, Philippines"><p class="data-note">On a shared device, always sign out. Your saved offline copy stays encrypted until you unlock it.</p></div><section class="panel auth-panel"><div class="auth-tabs" role="group" aria-label="Account action"><button class="button primary" id="choose-login" aria-pressed="true" type="button">Sign in</button><button class="button secondary" id="choose-register" aria-pressed="false" type="button">Create patient account</button></div><h2 id="auth-title">Welcome back.</h2><p id="auth-intro">Your barangay health worker can help you get started. Sign in to see your family’s records, or create a patient account. You can also unlock a saved copy when offline.</p><form id="auth-form"><div id="registration-name" hidden><label for="account-name">Your name</label><input id="account-name" autocomplete="name" maxlength="80"></div><label for="account-username">Username</label><input id="account-username" autocomplete="username" autocapitalize="none" spellcheck="false" minlength="3" maxlength="40" pattern="[a-zA-Z0-9][a-zA-Z0-9._-]{2,39}" required><p class="hint">3–40 letters, numbers, periods, underscores or hyphens.</p><label for="account-password">Password</label><input id="account-password" type="password" autocomplete="current-password" minlength="12" maxlength="128" required><p class="hint">At least 12 characters. Your password is never saved on this device.</p><p id="auth-error" class="notice warning" role="alert" hidden></p><p id="auth-success" class="notice good" role="status" hidden></p><button id="auth-submit" class="button primary" type="submit">Sign in / unlock offline copy ↗</button></form><p class="data-note">Staff access is approved by the clinic. Creating an account here always creates a patient account. Ask your health worker to link your profiles after registration.</p></section></main>`;
 document.body.insertBefore(view,$('#workspace-view'));
 const resumeStatus=document.createElement('p');resumeStatus.id='auth-resume';resumeStatus.className='notice good';resumeStatus.setAttribute('role','status');setText(resumeStatus,'Restoring your session…');$('.auth-panel').prepend(resumeStatus);
 function busy(value){$('#auth-main').setAttribute('aria-busy',String(value));$('#auth-form').hidden=value;$('.auth-tabs').hidden=value;resumeStatus.hidden=!value;for(const control of view.querySelectorAll('input,button'))control.disabled=value;}
 busy(true);
 let registration=false;
 function mode(value){registration=value;for(const [id,active] of [['choose-login',!value],['choose-register',value]]){const tab=$('#'+id);tab.classList.toggle('primary',active);tab.classList.toggle('secondary',!active);tab.setAttribute('aria-pressed',String(active));}$('#registration-name').hidden=!value;$('#account-name').required=value;setText($('#auth-title'),value?'A little closer to your care.':'Welcome back.');$('#account-password').autocomplete=value?'new-password':'current-password';setText($('#auth-submit'),value?'Create patient account ↗':'Sign in / unlock offline copy ↗');$('#auth-error').hidden=true;$('#auth-success').hidden=true;}
 $('#choose-login').onclick=()=>mode(false);$('#choose-register').onclick=()=>mode(true);
 $('#auth-form').onsubmit=async event=>{event.preventDefault();const button=$('#auth-submit');button.disabled=true;$('#auth-error').hidden=true;$('#auth-success').hidden=true;
  try{const username=$('#account-username').value,password=$('#account-password').value;
   if(registration){const result=await api('register',{method:'POST',body:{username,password,displayName:$('#account-name').value}});mode(false);setText($('#auth-success'),result.message);$('#auth-success').hidden=false;$('#account-password').value='';}
   else{const store=await AccountStore.signIn(username,password);$('#account-password').value='';onChange(store);}
  }catch(error){setText($('#auth-error'),error.message);$('#auth-error').hidden=false;}
  finally{button.disabled=false;}
 };
 return {show(){view.hidden=false;},hide(){view.hidden=true;},reset(){mode(false);$('#account-password').value='';},async restore(){try{const store=await AccountStore.resume();if(store)onChange(store);}catch(error){setText($('#auth-error'),error.message);$('#auth-error').hidden=false;}finally{busy(false);}}};
}
export async function patientAccess(store){
 const {accounts}=await api('accounts',{proof:store.proof});
 const profiles=[...store.data.mothers,...store.data.children];
 return ui`<p class="notice good">Confirm the person's identity with the clinic before linking a profile. Each account can see only the profiles selected here. Unlinking removes future cloud access; an already downloaded offline copy remains on that person's device.</p>${accounts.map(a=>ui`<form class="panel patient-link-form" data-account="${esc(a.id)}"><h2>${esc(a.displayName)}</h2><p>@${esc(a.username)}</p><fieldset><legend>Care profiles shared with this account</legend>${profiles.map(p=>ui`<label class="confirm-check"><input type="checkbox" name="patient" value="${esc(p.id)}" ${a.patientIds.includes(p.id)?'checked':''}><span>${esc(p.name)} · ${esc(p.id)}</span></label>`).join('')||markup('<p>Create a clinical profile first.</p>')}</fieldset><button class="button primary" type="submit">Save patient access</button><p class="link-result" role="status"></p></form>`).join('')||markup('<section class="panel"><h2>No patient accounts yet.</h2><p>Patients and guardians can register from the sign-in screen. Verify their identity, then link their care profiles here.</p></section>')}`;
}
export async function saveLinks(form,store){const button=form.querySelector('button');button.disabled=true;try{await api('links',{method:'PUT',proof:store.proof,body:{accountId:form.dataset.account,patientIds:new FormData(form).getAll('patient')}});setText(form.querySelector('.link-result'),'Patient access updated.');}catch(error){setText(form.querySelector('.link-result'),error.message);}finally{button.disabled=false;}}
